response_html:
{% macro row(label, value) -%}
<tr>
  <td style="width: 38%; padding: 10px 12px; border-bottom: 1px solid #e5e7eb; color: #4b5563; vertical-align: top;">{{ label }}</td>
  <td style="padding: 10px 12px; border-bottom: 1px solid #e5e7eb; color: #111827; font-weight: 600; vertical-align: top;">{{ value }}</td>
</tr>
{%- endmacro %}
{% set doc_link = frappe.utils.get_url_to_form("Leave Application", name) %}
{% set employee_display = employee_name or employee or "-" %}
{% set approver_display = leave_approver_name or leave_approver or "-" %}
{% set total_days = total_leave_days | default(none) %}
{% set balance = leave_balance | default(none) %}
{% set total_days_display = (total_days ~ " วัน") if total_days is not none else "-" %}
{% set balance_display = (balance ~ " วัน") if balance is not none else "-" %}
<div style="margin: 0; padding: 24px 12px; background: #f3f4f6; font-family: Arial, Tahoma, sans-serif; color: #111827;">
  <div style="max-width: 640px; margin: 0 auto; background: #ffffff; border: 1px solid #e5e7eb; border-radius: 12px; overflow: hidden;">
    <div style="padding: 24px 28px; background: #1d4ed8; color: #ffffff;">
      <div style="font-size: 24px; font-weight: 700; line-height: 1.35;">มีคำขอลาใหม่รอพิจารณา</div>
      <div style="margin-top: 6px; font-size: 14px; line-height: 1.6; color: #dbeafe;">กรุณาตรวจสอบรายละเอียดและดำเนินการอนุมัติหรือไม่อนุมัติในระบบ</div>
    </div>
    <div style="padding: 28px;">
      <p style="margin: 0 0 12px; line-height: 1.7;">เรียน {{ approver_display | e }},</p>
      <p style="margin: 0 0 24px; line-height: 1.7; color: #374151;">{{ employee_display | e }} ได้ส่งคำขอลาใหม่ โดยมีรายละเอียดดังต่อไปนี้</p>

      <table role="presentation" style="width: 100%; border-collapse: collapse; border: 1px solid #e5e7eb; font-size: 14px;">
        <tr>
          <td colspan="2" style="padding: 10px 12px; background: #eff6ff; color: #1e40af; font-weight: 700;">ข้อมูลคำขอ</td>
        </tr>
        {{ row("เลขที่ใบลา", (name or "-") | e) }}
        {{ row("วันที่ยื่นคำขอ", format_date(posting_date) | e) }}
        {{ row("สถานะ", "รอพิจารณา") }}
        <tr>
          <td colspan="2" style="padding: 10px 12px; background: #eff6ff; color: #1e40af; font-weight: 700;">ข้อมูลพนักงาน</td>
        </tr>
        {{ row("ชื่อพนักงาน", employee_display | e) }}
        {{ row("รหัสพนักงาน", (employee or "-") | e) }}
        {{ row("บริษัท", (company or "-") | e) }}
        {{ row("แผนก", (department or "-") | e) }}
        <tr>
          <td colspan="2" style="padding: 10px 12px; background: #eff6ff; color: #1e40af; font-weight: 700;">รายละเอียดการลา</td>
        </tr>
        {{ row("ประเภทการลา", (leave_type or "-") | e) }}
        {{ row("ตั้งแต่วันที่", format_date(from_date) | e) }}
        {{ row("ถึงวันที่", format_date(to_date) | e) }}
        {{ row("จำนวนวันลา", total_days_display | e) }}
        {% if half_day %}
          {{ row("ครึ่งวัน", (("ใช่ — วันที่ " ~ format_date(half_day_date)) if half_day_date else "ใช่") | e) }}
        {% else %}
          {{ row("ครึ่งวัน", "ไม่ใช่") }}
        {% endif %}
        {{ row("ยอดลาก่อนยื่นคำขอ", balance_display | e) }}
        {{ row("เหตุผลการลา", (description or "-") | e | replace("\n", "<br>")) }}
        {{ row("ผู้อนุมัติ", approver_display | e) }}
      </table>

      <div style="margin-top: 26px; text-align: center;">
        <a href="{{ doc_link | e }}" target="_blank" rel="noopener noreferrer" style="display: inline-block; padding: 12px 22px; border-radius: 7px; background: #1d4ed8; color: #ffffff; font-size: 14px; font-weight: 700; text-decoration: none;">เปิดใบลาเพื่อพิจารณา</a>
      </div>
      <p style="margin: 24px 0 0; color: #6b7280; font-size: 12px; line-height: 1.6; text-align: center;">อีเมลฉบับนี้ส่งจากระบบอัตโนมัติ กรุณาดำเนินการผ่านลิงก์ด้านบน</p>
    </div>
  </div>
</div>

{% macro row(label, value) -%}
<tr>
  <td style="width: 38%; padding: 10px 12px; border-bottom: 1px solid #e5e7eb; color: #4b5563; vertical-align: top;">{{ label }}</td>
  <td style="padding: 10px 12px; border-bottom: 1px solid #e5e7eb; color: #111827; font-weight: 600; vertical-align: top;">{{ value }}</td>
</tr>
{%- endmacro %}
{% set doc_link = frappe.utils.get_url_to_form("Leave Application", name) %}
{% set employee_display = employee_name or employee or "-" %}
{% set approver_display = leave_approver_name or leave_approver or "-" %}
{% set total_days = total_leave_days | default(none) %}
{% set balance = leave_balance | default(none) %}
{% set total_days_display = (total_days ~ " วัน") if total_days is not none else "-" %}
{% set balance_display = (balance ~ " วัน") if balance is not none else "-" %}
{% if status == "Approved" %}
  {% set status_label = "อนุมัติแล้ว" %}
  {% set status_title = "ใบลาของคุณได้รับการอนุมัติแล้ว" %}
  {% set status_message = "คำขอลาของคุณผ่านการพิจารณาและได้รับการอนุมัติเรียบร้อยแล้ว" %}
  {% set header_color = "#047857" %}
  {% set header_text_color = "#d1fae5" %}
{% elif status == "Rejected" %}
  {% set status_label = "ไม่อนุมัติ" %}
  {% set status_title = "ใบลาของคุณไม่ได้รับการอนุมัติ" %}
  {% set status_message = "คำขอลาของคุณผ่านการพิจารณาแล้วและไม่ได้รับการอนุมัติ" %}
  {% set header_color = "#b91c1c" %}
  {% set header_text_color = "#fee2e2" %}
{% elif status == "Cancelled" %}
  {% set status_label = "ยกเลิกแล้ว" %}
  {% set status_title = "ใบลาของคุณถูกยกเลิกแล้ว" %}
  {% set status_message = "คำขอลารายการนี้ถูกยกเลิกในระบบเรียบร้อยแล้ว" %}
  {% set header_color = "#4b5563" %}
  {% set header_text_color = "#f3f4f6" %}
{% else %}
  {% set status_label = status or "อัปเดตแล้ว" %}
  {% set status_title = "สถานะใบลาของคุณได้รับการอัปเดต" %}
  {% set status_message = "กรุณาตรวจสอบสถานะล่าสุดและรายละเอียดในระบบ" %}
  {% set header_color = "#1d4ed8" %}
  {% set header_text_color = "#dbeafe" %}
{% endif %}
<div style="margin: 0; padding: 24px 12px; background: #f3f4f6; font-family: Arial, Tahoma, sans-serif; color: #111827;">
  <div style="max-width: 640px; margin: 0 auto; background: #ffffff; border: 1px solid #e5e7eb; border-radius: 12px; overflow: hidden;">
    <div style="padding: 24px 28px; background: {{ header_color }}; color: #ffffff;">
      <div style="font-size: 24px; font-weight: 700; line-height: 1.35;">{{ status_title }}</div>
      <div style="margin-top: 6px; font-size: 14px; line-height: 1.6; color: {{ header_text_color }};">{{ status_message }}</div>
    </div>
    <div style="padding: 28px;">
      <p style="margin: 0 0 12px; line-height: 1.7;">เรียน {{ employee_display | e }},</p>
      <p style="margin: 0 0 24px; line-height: 1.7; color: #374151;">ผลการพิจารณาคำขอลาของคุณได้รับการบันทึกในระบบแล้ว โดยมีรายละเอียดดังต่อไปนี้</p>

      <table role="presentation" style="width: 100%; border-collapse: collapse; border: 1px solid #e5e7eb; font-size: 14px;">
        <tr>
          <td colspan="2" style="padding: 10px 12px; background: #f9fafb; color: #374151; font-weight: 700;">ผลการพิจารณา</td>
        </tr>
        {{ row("เลขที่ใบลา", (name or "-") | e) }}
        {{ row("สถานะ", status_label) }}
        {{ row("ผู้อนุมัติ", approver_display | e) }}
        <tr>
          <td colspan="2" style="padding: 10px 12px; background: #f9fafb; color: #374151; font-weight: 700;">ข้อมูลพนักงาน</td>
        </tr>
        {{ row("ชื่อพนักงาน", employee_display | e) }}
        {{ row("รหัสพนักงาน", (employee or "-") | e) }}
        {{ row("บริษัท", (company or "-") | e) }}
        {{ row("แผนก", (department or "-") | e) }}
        <tr>
          <td colspan="2" style="padding: 10px 12px; background: #f9fafb; color: #374151; font-weight: 700;">รายละเอียดการลา</td>
        </tr>
        {{ row("ประเภทการลา", (leave_type or "-") | e) }}
        {{ row("ตั้งแต่วันที่", format_date(from_date) | e) }}
        {{ row("ถึงวันที่", format_date(to_date) | e) }}
        {{ row("จำนวนวันลา", total_days_display | e) }}
        {% if half_day %}
          {{ row("ครึ่งวัน", (("ใช่ — วันที่ " ~ format_date(half_day_date)) if half_day_date else "ใช่") | e) }}
        {% else %}
          {{ row("ครึ่งวัน", "ไม่ใช่") }}
        {% endif %}
        {{ row("ยอดลาก่อนยื่นคำขอ", balance_display | e) }}
        {{ row("เหตุผลการลา", (description or "-") | e | replace("\n", "<br>")) }}
      </table>

      <div style="margin-top: 26px; text-align: center;">
        <a href="{{ doc_link | e }}" target="_blank" rel="noopener noreferrer" style="display: inline-block; padding: 12px 22px; border-radius: 7px; background: {{ header_color }}; color: #ffffff; font-size: 14px; font-weight: 700; text-decoration: none;">เปิดดูใบลา</a>
      </div>
      <p style="margin: 24px 0 0; color: #6b7280; font-size: 12px; line-height: 1.6; text-align: center;">อีเมลฉบับนี้ส่งจากระบบอัตโนมัติ กรุณาตรวจสอบรายละเอียดล่าสุดในระบบ</p>
    </div>
  </div>
</div>
